	protected Category read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Category" );

		Category entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Category with primary key" );
		msg.append( categoryId );
		
		CategoryFetchOneSummary fetchOneSummary = new CategoryFetchOneSummary( categoryId );

		try {
			entity = CategoryService.getCategoryInstance().getCategory( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Category " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Category.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Category." );

		StringBuilder msg = new StringBuilder( "Failed to update a Category : " );        
		Category entity = read();
		UpdateCategoryCommand command = generateUpdateCommand();
		command.setCategoryId(entity.getCategoryId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Category." );

			// for use later on...
			categoryId = entity.getCategoryId();

			CategoryService proxy = CategoryService.getCategoryInstance();  

			proxy.updateCategory( command ).get();

			LOGGER.info( "-- Successfully saved Category - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + categoryId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Category.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Category." );

		Category entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Category with id " + categoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Category with id " + categoryId );

			throw e;
		}

		try{
			CategoryService.getCategoryInstance().delete( new DeleteCategoryCommand( entity.getCategoryId() ) ).get();
			LOGGER.info( "-- Successfully deleted Category with id " + categoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Category with id " + categoryId );

			throw e;
		}
	}

	/**
	 * get all Categorys.
	 */
	protected List<Category> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Categorys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Category : " );        
		List<Category> collection  = new ArrayList<>();

		try {
			// call the static get method on the CategoryService
			collection = CategoryService.getCategoryInstance().getAllCategory();
			assertNotNull( collection, "An Empty collection of Category was incorrectly returned.");
			
			// Now print out the values
			Category entity = null;            
			Iterator<Category> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCategoryId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

